import{z as i,x as s,o as A,c as d,q as l,j as o,D as e,d as a,s as r,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"模型选择协议","description":"","frontmatter":{"title":"模型选择协议","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-model-selection-protocol.md","filePath":"quant/fml-model-selection-protocol.md","lastUpdated":1791063341000}'),C={name:"quant/fml-model-selection-protocol.md"};function p(D,E,m,f,h,u){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="模型选择协议" tabindex="-1">模型选择协议 <a class="header-anchor" href="#模型选择协议" aria-label="Permalink to &quot;模型选择协议&quot;">​</a></h1><div class="epigraph"><p>在 $N$ 次尝试里挑最大值，最大值本身就是被选择过程污染的统计量；协议的作用不是让尝试变少，而是让每一次尝试都被计数。</p><footer>—— 据 Harvey, Liu and Zhu, Review of Financial Studies, 2016；Bailey and López de Prado, Journal of Portfolio Management, 2014 整理</footer></div><p><a href="/quant/fml-label-engineering-deep">上一课</a>把标签冻结成四元组，\\(X\\) 与 \\(y\\) 都有了契约。缺口在中间那一步：「在候选里挑谁」这件事本身是统计过程，却常常没有过程——网格扫一遍、挑折外最好的那个，选择的有偏性顺着这条缝进验收。<a href="/quant/nested-cv">嵌套交叉验证</a>已把选择关进内层，<a href="/quant/pbo">Probability of Backtest Overfitting</a>已度量选择过程的质量。本课写协议：候选集、网格、判据、\\(N\\) 台账与晋升判据怎么落成制度。后课的切分是这协议的裁判。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选择是一个估计器：非嵌套的「折外最优」是候选最大值的期望，有系统性上偏，这是<a href="/quant/nested-cv">嵌套交叉验证</a>的结论。协议要堵的是三种实践中更常见的失真。\\(N\\) 不可见：网格条数写进了文档，但桌下的「顺手试了两个特征」「换个种子再跑一次」不进任何台账，名义 \\(N\\) 被系统性低估。判据漂移：看到结果之后改验收线——夏普不够就换 Calmar，扣费后不够就改报扣费前——判据变成了被选择的第二个候选。冠军外推：内层赢不保证外层赢，外层赢更不保证实盘赢；把三层证书压成一张是选择协议最常见的省略。缺口：把「谁顺手谁说了算」变成可审计的程序。</p><p><span class="marginnote">选择污染可以类比 1000 只猴子各扔 10 次硬币：必然有一只十次全正，但「表现最好」不等于「会扔硬币」。从 \\(N\\) 个候选里挑出的最高分，被挑选过程系统性地抬高了——冠军的分数不能按字面读，这正是协议要先于数据定判据的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议五要素。候选集与网格预注册，修改留痕；判据定在看到数据之前，单一主判据加若干次要观测，明写「次要观测不用于翻案」；\\(N\\) 台账对每次训练、每次特征增删、每个阈值计数，其输出直接对接 <a href="/quant/deflated-sharpe">Deflated Sharpe</a> 的 \\(N\\) 输入；评估关用外层折加 <a href="/quant/pbo">PBO</a>，前者评候选，后者评选择过程本身；晋升判据含弃权——全部不达标是合法输出，且应按零假设的先验预期其最常见。运行上分两区：探索区随便试，notebook 不设限；验收区必须按协议从头重跑，探索次数按折价并入 \\(N\\) 台账。两区的唯一通道是重跑，不是汇报。</p><p><span class="marginnote">PBO（回测过拟合概率）翻译成大白话：把数据切成两半各选一次冠军，反复做，统计「两半选出的冠军不是同一个」的频率——频率高，说明「选冠军」这道工序本身在追噪声，冠军的折外成绩多是挑选红利。</span></p>',9)),(A(),o(n,null,{default:e(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E5%80%99%E9%80%89%E9%9B%86%E4%B8%8E%E7%BD%91%E6%A0%BC%EF%BC%9A%E9%A2%84%E6%B3%A8%E5%86%8C%E7%95%99%E7%97%95%22%5D%20--%3E%20SEL%5B%22%E5%86%85%E5%B1%82%EF%BC%9A%E5%B5%8C%E5%A5%97%E9%80%89%E6%8B%A9%22%5D%0A%20%20SEL%20--%3E%20OOS%5B%22%E5%A4%96%E5%B1%82%E6%8A%98%E5%A4%96%E8%AF%84%E4%BC%B0%22%5D%0A%20%20OOS%20--%3E%20PBO%5B%22PBO%EF%BC%9A%E5%BA%A6%E9%87%8F%E9%80%89%E6%8B%A9%E8%BF%87%E7%A8%8B%22%5D%0A%20%20PBO%20--%3E%20LED%5B%22N%20%E5%8F%B0%E8%B4%A6%EF%BC%9A%E8%AE%AD%E7%BB%83%E3%80%81%E7%89%B9%E5%BE%81%E3%80%81%E9%98%88%E5%80%BC%22%5D%0A%20%20LED%20--%3E%20DSR%5B%22%E6%8A%98%E4%BB%B7%E5%90%8E%E5%88%A4%E6%8D%AE%EF%BC%9A%E5%AE%9A%E5%9C%A8%E7%9C%8B%E5%88%B0%E6%95%B0%E6%8D%AE%E5%89%8D%22%5D%0A%20%20DSR%20--%3E%7C%22%E8%BE%BE%E6%A0%87%22%7C%20PROM%5B%22%E6%99%8B%E5%8D%87%E5%80%99%E9%80%89%22%5D%0A%20%20DSR%20--%3E%7C%22%E4%B8%8D%E8%BE%BE%E6%A0%87%22%7C%20ABSTAIN%5B%22%E5%BC%83%E6%9D%83%EF%BC%9A%E5%90%88%E6%B3%95%E8%BE%93%E5%87%BA%22%5D%0A%20%20ABSTAIN%20--%3E%7C%22%E6%96%B0%E6%83%B3%E6%B3%95%E5%9B%9E%E6%8E%A2%E7%B4%A2%E5%8C%BA%22%7C%20REG%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("多重检验折价为什么不可豁免：\\(N\\) 个零真候选里，最大统计量按 \\(\\sqrt{2\\log N}\\) 随 \\(N\\) 增长，"),B("a",{href:"/quant/deflated-sharpe"},"Deflated Sharpe"),a(" 与 Harvey–Liu–Zhu 的多重折价都是这一极值直觉的落地。金融里候选彼此相关——同一批数据的不同变换——有效 \\(N\\) 小于名义 \\(N\\)，这本是好消息；但「没写下来的尝试」让有效 \\(N\\) 从可估计变成不可估计，台账的首要功能因此不是精确计数，而是阻止 \\(N\\) 被系统性低估。弃权为什么是功能：若零假设为真，协议的产出分布应以「无新模型」为众数；一个每轮都产出冠军的协议只是仪式，它的真假设早已在探索区被消耗。")],-1)),(A(),o(n,null,{default:e(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20EX%5B%22%E6%8E%A2%E7%B4%A2%E5%8C%BA%EF%BC%9A%E9%9A%8F%E4%BE%BF%E8%AF%95%EF%BC%8C%E4%B8%8D%E8%AE%BE%E9%99%90%22%5D%20--%3E%20LOG%5B%22%E5%B0%9D%E8%AF%95%E6%8C%89%E6%8A%98%E4%BB%B7%E5%B9%B6%E5%85%A5%20N%20%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20LOG%20--%3E%20IDEA%5B%22%E5%80%99%E9%80%89%E6%83%B3%E6%B3%95%E5%AE%9A%E5%9E%8B%22%5D%0A%20%20IDEA%20--%3E%20RERUN%5B%22%E6%8C%89%E5%8D%8F%E8%AE%AE%E4%BB%8E%E5%A4%B4%E9%87%8D%E8%B7%91%22%5D%0A%20%20RERUN%20--%3E%20AC%5B%22%E9%AA%8C%E6%94%B6%E5%8C%BA%EF%BC%9A%E9%A2%84%E6%B3%A8%E5%86%8C%E5%8D%95%E4%B8%80%E4%B8%BB%E5%88%A4%E6%8D%AE%22%5D%0A%20%20AC%20--%3E%7C%22%E8%BE%BE%E6%A0%87%22%7C%20PROM%5B%22%E6%99%8B%E5%8D%87%E5%80%99%E9%80%89%22%5D%0A%20%20AC%20--%3E%7C%22%E4%B8%8D%E8%BE%BE%E6%A0%87%22%7C%20ABS%5B%22%E5%BC%83%E6%9D%83%EF%BC%9A%E5%90%88%E6%B3%95%E8%BE%93%E5%87%BA%22%5D%0A%20%20IDEA%20-.-%3E%7C%22%E7%9B%B4%E6%8E%A5%E6%B1%87%E6%8A%A5%E8%BF%9B%E9%AA%8C%E6%94%B6%22%7C%20X%5B%22%E6%A1%8C%E4%B8%8B%E9%80%9A%E9%81%93%EF%BC%9A%E5%8D%8F%E8%AE%AE%E5%A4%96%22%5D%0A%20%20X%20--%3E%20BAD%5B%22N%20%E4%B8%8D%E5%8F%AF%E4%BC%B0%EF%BC%9A%E6%8A%98%E4%BB%B7%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">常见误区：把换判据当成「换个角度看」。看到夏普不够再改用 Calmar，等于考砸后换一张评分表——判据本身成了被挑选的第二个候选，多重检验的账要再翻一倍，而这份翻倍通常没人记进 \\(N\\)。</span></p><p><span class="marginnote">\\(\\sqrt{2\\log N}\\) 的量级：\\(N=100\\) 时约 \\(3.0\\)，\\(N=1000\\) 时约 \\(3.7\\)。台账只记了 10 次而桌上实际发生过 100 次，门槛就低了约 \\(0.7\\) 个标准差——被低估的是 \\(N\\)，被低估的门槛放进来的是噪声。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>嵌套结构与 CSCV 的机制、Reality Check 与 SPA 的检验量选择都已有专课，本课只引用。协议不保证找到 alpha：它约束的是假阳性率，不是功效；真信号稀薄时，弃权率高是协议正常工作的证据而非失败。协议也不替你定判据——主判据选扣费后效用还是截面 IC，是投资目标的问题，协议只要求它先于数据被写下。桌面下的尝试无法被协议观测，只能被组织约束，这是本课程工作流一课的题目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选择是估计器，非嵌套折外分数是候选最大值的有偏期望。</li><li>协议五要素：预注册候选、先于数据的判据、\\(N\\) 台账、外层加 PBO 的评估、含弃权的晋升判据。</li><li>探索区与验收区分离，唯一通道是按协议重跑，探索次数折价并入 \\(N\\)。</li><li>台账的首要功能是阻止 \\(N\\) 被系统性低估；每轮必出冠军的协议是仪式。</li><li>出处：Harvey, Liu and Zhu, <em>RFS</em>, 2016；Bailey and López de Prado, <em>JPM</em>, 2014；Cawley and Talbot, <em>JMLR</em>, 2010。</li></ul>',6))])}const F=i(C,[["render",p]]);export{N as __pageData,F as default};
